// In-browser version of the API's /predict (api/main.py).
// Params come from checkpoints/logreg_combined_params.json, written by
// LogisticRegression/export_params.py. logreg.test.ts checks this file
// against responses generated by the API itself.

export interface ModelParams {
  model: string
  amyloid_rois: string[]
  tau_rois: string[]
  feature_names: string[]
  scaler_mean: number[]
  scaler_scale: number[]
  coef: number[]
  intercept: number
  shap_background_mean: number[]
}

/** ROI name -> SUVR value, the same shape as the API request fields. */
export type Suvrs = Record<string, number>

export interface ShapContribution {
  roi: string
  shap_value: number
  direction: 'toward_AD' | 'toward_CN'
}

/** Same fields as the API's PredictResponse, without rounding. */
export interface Prediction {
  predicted_class: 'AD' | 'CN'
  probability_ad: number
  probability_cn: number
  shap_contributions: ShapContribution[]
}

// The API rounds probabilities to 4 decimals and SHAP values to 6. Rounding
// can be off by exactly half a unit, so allow one full unit in the last digit
export const PROB_TOLERANCE = 1e-4
export const SHAP_TOLERANCE = 1e-6

const round = (value: number, digits: number) => Number(value.toFixed(digits))

export function predict(params: ModelParams, amyloid: Suvrs, tau: Suvrs): Prediction {
  // Training order: amyloid ROIs then tau ROIs
  const x = [...params.amyloid_rois.map((r) => amyloid[r]), ...params.tau_rois.map((r) => tau[r])]
  const z = x.map((v, i) => (v - params.scaler_mean[i]) / params.scaler_scale[i])

  const logit = z.reduce((sum, zi, i) => sum + params.coef[i] * zi, params.intercept)
  const probAd = 1 / (1 + Math.exp(-logit))

  // Linear SHAP (interventional): coef * (z - background mean)
  const contributions: ShapContribution[] = z.map((zi, i) => {
    const value = params.coef[i] * (zi - params.shap_background_mean[i])
    return {
      roi: params.feature_names[i],
      shap_value: value,
      direction: value > 0 ? 'toward_AD' : 'toward_CN',
    }
  })
  // The API sorts by the value rounded to 6 decimals (stable sort), so ties match
  contributions.sort((a, b) => Math.abs(round(b.shap_value, 6)) - Math.abs(round(a.shap_value, 6)))

  return {
    predicted_class: probAd >= 0.5 ? 'AD' : 'CN',
    probability_ad: probAd,
    probability_cn: 1 - probAd,
    shap_contributions: contributions,
  }
}

/** Form defaults: training-set mean SUVR per ROI, rounded to 4 decimals. */
export function defaultInputs(params: ModelParams): { amyloid: Suvrs; tau: Suvrs } {
  const n = params.amyloid_rois.length
  const toSuvrs = (rois: string[], offset: number) =>
    Object.fromEntries(rois.map((r, i) => [r, round(params.scaler_mean[offset + i], 4)]))
  return { amyloid: toSuvrs(params.amyloid_rois, 0), tau: toSuvrs(params.tau_rois, n) }
}
